head.script:
scwin.fn_SetPar, scwin.strCdSch;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.rdochange();
        window.document.body.scroll = "no";
        let arrPar = new Array();
        const parentWin = $c.frame.path("../");
        scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
        // fn_list_sync();
        txb_Search_1.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92015.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txb_Search_1_onkeydown
 * @description txb_Search_1 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_Search_1_onkeydown = async function() {
    try {
        if (event.keyCode === 13) {
            if (rdo_searchType.getValue() === "1") {
                if ($c.ut.cIsNull(txb_Search_1.getValue())) {
                    await $c.win.alert("검색할 도로명을 입력해 주세요.");
                    txb_Search_1.focus();
                    return false;
                }
                if (!await scwin.checkSearchWord(txb_Search_1.getValue(), "도로명")) {
                    txb_Search_1.focus();
                    return false;
                }
            } else {
                if ($c.ut.cIsNull(txb_Search_2.getValue())) {
                    await $c.win.alert("검색할 건물명을 입력해 주세요.");
                    txb_Search_2.focus();
                    return false;
                }
                if (!await scwin.checkSearchWord(txb_Search_2.getValue(), "건물명")) {
                    txb_Search_2.focus();
                    return false;
                }
            }
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92015.txb_Search_1_onkeydown" });
    }
};

/**
 * @method
 * @name txb_Search_2_onkeydown
 * @description txb_Search_2 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
