};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92015.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotCnt.setValue("총 " + rowcount + " 건");
        if (scwin.strCdSch !== "") {
            for (let i = 1; i <= dts_List.getRowCount(); i++) {
                if (scwin.strCdSch === dts_List.getCellData(i, 1)) {
                    dts_List.setRowPosition(i, 0);
                    break;
                }
            }
            scwin.strCdSch = "";
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92015.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name rdo_searchType_onselchange
 * @description rdo_searchType onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_searchType_onselchange = function() {
    try {
        scwin.rdochange();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92015.rdo_searchType_onselchange" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        let arrPar = new Array();
        if (scwin.fn_SetPar !== undefined) {
            arrPar[0] = dts_List.getCellData(dts_List.getRowPosition(), 'ZIPCD');
            arrPar[1] = dts_List.getCellData(dts_List.getRowPosition(), 'ADDR');
            arrPar[2] = dts_List.getCellData(dts_List.getRowPosition(), 'ZIPCD_SEQ');
            scwin.fn_SetPar(arrPar);
        }
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92015.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        if (rdo_searchType.getValue() === "1") {
            if ($c.ut.cIsNull(txb_Search_1.getValue())) {
                await $c.win.alert("검색할 도로명을 입력해 주세요.");
                txb_Search_1.focus();
                return false;
            }
            if (!await scwin.checkSearchWord(txb_Search_1.getValue(), "도로명")) {
                txb_Search_1.focus();
                return false;
            }
        } else {
            if ($c.ut.cIsNull(txb_Search_2.getValue())) {
                await $c.win.alert("검색할 건물명을 입력해 주세요.");
                txb_Search_2.focus();
                return false;
            }
            if (!await scwin.checkSearchWord(txb_Search_2.getValue(), "건물명")) {
                txb_Search_2.focus();
                return false;
            }
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92015.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92015.img_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&inputMessageId=ZIPCD_OUT&outputMessageId=ZIPCD_OUT";
    url += "&SEARCHTYPE=" + rdo_searchType.getValue() + "&SEARCHDTL_1=" + txb_Search_1.getValue() + "&SEARCHDTL_2=" + txb_Search_2.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name rdochange
 * @description rdochange 처리
 * @returns {void}
 * @hidden N
 */
scwin.rdochange = function() {
    if (rdo_searchType.getValue() === "1") {
        panel_1.show("");
        panel_2.hide();
        label_3.show("");
        label_9.hide();
    } else {
        panel_1.hide();
        panel_2.show("");
        label_3.hide();
        label_9.show("");
    }
};

/**
 * @method
 * @name checkSearchWord
 * @description check Search Word 처리
 * @param {*} pWord pWord
 * @param {*} type type
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSearchWord = async function(pWord, type) {
    const word = $c.stf.trim(pWord);
    const reg = new RegExp(/[%]/g);
    if (reg.test(pWord)) {
        await $c.win.alert("%는 사용할 수 없습니다.");
        return false;
    }
    if (word.length < 2) {
        await $c.win.alert(type + "은 두글자 이상 입력되어야 합니다.");
        return false;
    }
    return true;
};
